  // src/site/pages.ts, src/music/chord-theory.ts: Akkordseiten
  "kleine Sekunde": "seconde mineure",
  "große Sekunde": "seconde majeure",
  "kleine Terz": "tierce mineure",
  "große Terz": "tierce majeure",
  "Quarte": "quarte",
